export const DAILY_GEM_PROFILES = Object.freeze(Object.fromEntries(
  DAILY_GEMS.map((gem) => [gem.id, Object.freeze(gem)])
));

export const DAILY_GEM_IDS = Object.freeze(DAILY_GEMS.map((gem) => gem.id));

export function dailyGemForDate(dateLike) {
  const source = dateLike instanceof Date ? dateLike : new Date(dateLike);
  const valid = !Number.isNaN(source.getTime());
  const month = valid ? source.getMonth() + 1 : 1;
  const day = valid ? source.getDate() : 1;
  const commonYearMonthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const normalizedDay = month === 2 && day === 29 ? 28 : day;
  const dayOfYear = commonYearMonthLengths
    .slice(0, month - 1)
    .reduce((sum, value) => sum + value, 0) + normalizedDay;
  const id = DAILY_GEM_IDS[Math.max(0, Math.min(364, dayOfYear - 1))];
  return DAILY_GEM_PROFILES[id];
}
